-- Accident Manager - Synthetic Demo Data
-- Dependencies: 01-schema.sql and 02-seed.sql
-- Fictional reports and comments; geographic data from OpenStreetMap.
-- (c) OpenStreetMap contributors, ODbL: https://www.openstreetmap.org/copyright
-- Generated by scripts/generate_demo_sql.py. Do not edit generated rows manually.
-- Development/demo only; seed accounts use the existing NEEDS_HASHING mechanism.

BEGIN;
SET LOCAL standard_conforming_strings = on;
SET LOCAL client_encoding = 'UTF8';

-- Serialise concurrent executions of this seed.
SELECT pg_advisory_xact_lock(483721, 3);

CREATE TEMP TABLE demo_users (
    name text, email text PRIMARY KEY
) ON COMMIT DROP;

CREATE TEMP TABLE demo_incidents (
    accident_id uuid PRIMARY KEY, reporter_email text,
    title text, description text, status public.accident_status,
    category public.incident_category, severity public.incident_severity,
    longitude double precision, latitude double precision,
    created_offset integer, updated_offset integer,
    starts_offset integer, ends_offset integer
) ON COMMIT DROP;

CREATE TEMP TABLE demo_comments (
    comment_id uuid PRIMARY KEY, accident_id uuid REFERENCES demo_incidents,
    author_email text, content text,
    created_offset integer, updated_offset integer
) ON COMMIT DROP;

DO $seed$
DECLARE
    existing_incidents integer;
    existing_comments integer;
    inserted_count integer;
BEGIN
    SELECT count(*) INTO existing_incidents
    FROM public.accidents a JOIN demo_incidents d USING (accident_id);
    SELECT count(*) INTO existing_comments
    FROM public.comments c JOIN demo_comments d USING (comment_id);

    -- Do not overwrite edited demo records or rebase their original timestamps.
    IF existing_incidents = 98 AND existing_comments = 30 THEN
        RAISE NOTICE 'Demo dataset already exists; no changes made.';
        RETURN;
    ELSIF existing_incidents <> 0 OR existing_comments <> 0 THEN
        RAISE EXCEPTION 'Partial demo dataset detected. No changes made.';
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM public.users
        WHERE user_id = '11111111-1111-1111-1111-111111111111' AND email = 'admin@student.com' AND role = 'admin'
    ) THEN
        RAISE EXCEPTION 'Original seed administrator missing. Run 02-seed.sql first on a fresh database.';
    END IF;

    -- 1. Citizens and project team. Preserve existing passwords and roles.
    SELECT name, email, 'NEEDS_HASHING', 'user', true,
           CURRENT_TIMESTAMP - INTERVAL '180 days'
    FROM demo_users
    ON CONFLICT (email) DO NOTHING;

    -- Backdate only seed accounts so they predate their fictional activity.
    UPDATE public.users u
    SET created_at = LEAST(COALESCE(u.created_at, CURRENT_TIMESTAMP),
                           CURRENT_TIMESTAMP - INTERVAL '180 days')
    FROM demo_users d
    WHERE u.email = d.email
      AND (u.created_at IS NULL OR u.created_at > CURRENT_TIMESTAMP - INTERVAL '180 days');

    -- The original admin also authored historical demo comments.
    -- Adjust only its creation timestamp if needed, not its password or role.
    UPDATE public.users
    SET created_at = LEAST(COALESCE(created_at, CURRENT_TIMESTAMP),
                          CURRENT_TIMESTAMP + (
                              SELECT min(created_offset) - 1
                              FROM demo_comments WHERE author_email = 'admin@student.com'
                          ) * INTERVAL '1 minute')
    WHERE user_id = '11111111-1111-1111-1111-111111111111';

    -- 2. Incidents. UUIDs are deterministic; user IDs are resolved by email.
        accident_id, reporter_id, title, description, status, category,
        severity, location, created_at, updated_at, starts_at, ends_at
    )
    SELECT d.accident_id, u.user_id, d.title, d.description, d.status,
           d.category, d.severity,
           ST_SetSRID(ST_MakePoint(d.longitude, d.latitude), 4326),
           CURRENT_TIMESTAMP + d.created_offset * INTERVAL '1 minute',
           CURRENT_TIMESTAMP + d.updated_offset * INTERVAL '1 minute',
           CURRENT_TIMESTAMP + d.starts_offset * INTERVAL '1 minute',
           CURRENT_TIMESTAMP + d.ends_offset * INTERVAL '1 minute'
    FROM demo_incidents d JOIN public.users u ON u.email = d.reporter_email;

    GET DIAGNOSTICS inserted_count = ROW_COUNT;
    IF inserted_count <> 98 THEN
        RAISE EXCEPTION 'Expected 98 incidents; inserted %.', inserted_count;
    END IF;

    -- 3. Historical comments. Foreign keys reference the seeded incidents.
        comment_id, author_id, accident_id, content, created_at, updated_at
    )
    SELECT d.comment_id, u.user_id, d.accident_id, d.content,
           CURRENT_TIMESTAMP + d.created_offset * INTERVAL '1 minute',
           CURRENT_TIMESTAMP + d.updated_offset * INTERVAL '1 minute'
    FROM demo_comments d JOIN public.users u ON u.email = d.author_email;

    GET DIAGNOSTICS inserted_count = ROW_COUNT;
    IF inserted_count <> 30 THEN
        RAISE EXCEPTION 'Expected 30 comments; inserted %.', inserted_count;
    END IF;

    RAISE NOTICE 'Inserted 98 demo incidents and 30 demo comments.';
END;
$seed$;

COMMIT;
